docs.validate_doc_update:
function (newDoc, oldDoc, userCtx, secObj) {
  if (newDoc._deleted === true) { return; }
  if (newDoc._id && newDoc._id.indexOf("_design/") === 0) { return; }

  var allowedTypes = ["customer", "staff", "product", "voucher", "shipping_method", "cart", "order", "review"];
  if (allowedTypes.indexOf(newDoc.type) === -1) {
    throw({forbidden: "type is required and must be supported"});
  }
  if (newDoc.schema_version !== 2) {
    throw({forbidden: "business documents must use schema_version 2"});
  }

  function nonNegative(value) {
    return typeof value === "number" && isFinite(value) && value >= 0;
  }
  function integer(value) {
    return typeof value === "number" && isFinite(value) && Math.floor(value) === value;
  }
  function validItems(items) {
    if (!Array.isArray(items)) { return false; }
    for (var i = 0; i < items.length; i++) {
      var item = items[i];
      if (!item || typeof item !== "object") { return false; }
      if (typeof item.variant_id !== "string" || item.variant_id.length === 0) { return false; }
      if (!integer(item.quantity) || item.quantity <= 0) { return false; }
    }
    return true;
  }

  if (newDoc.type === "customer" || newDoc.type === "staff") {
    if (!newDoc.legacy_id || !newDoc.auth || !newDoc.profile || typeof newDoc.active !== "boolean") {
      throw({forbidden: "account requires legacy_id, auth, profile, and active"});
    }
    if (!newDoc.auth.username || typeof newDoc.auth.requires_password_reset !== "boolean") {
      throw({forbidden: "account requires username and reset flag"});
    }
    if (newDoc.auth.requires_password_reset !== true && !newDoc.auth.password_hash) {
      throw({forbidden: "account needs a password hash or a required reset"});
    }
    if (newDoc.type === "staff" && ["manager", "staff"].indexOf(newDoc.role) === -1) {
      throw({forbidden: "staff role is invalid"});
    }
  }

  if (newDoc.type === "product") {
    if (!newDoc.legacy_id || !newDoc.name || !newDoc.category || !Array.isArray(newDoc.variants) || newDoc.variants.length === 0) {
      throw({forbidden: "product requires legacy_id, name, category, and variants"});
    }
    if (!Array.isArray(newDoc.images) || typeof newDoc.active !== "boolean") {
      throw({forbidden: "product requires images and active"});
    }
    for (var p = 0; p < newDoc.variants.length; p++) {
      var variant = newDoc.variants[p];
      if (!variant.variant_id || !variant.size || !nonNegative(variant.price) ||
          !integer(variant.stock) || variant.stock < 0 || typeof variant.active !== "boolean") {
        throw({forbidden: "product variant has invalid id, size, price, stock, or active flag"});
      }
    }
  }

  if (newDoc.type === "cart") {
    if (!newDoc.customer_id || !validItems(newDoc.items)) {
      throw({forbidden: "cart requires customer_id and positive item quantities"});
    }
  }

  if (newDoc.type === "voucher") {
    if (!newDoc.code || ["percent", "cash", "shipping"].indexOf(newDoc.discount_type) === -1 ||
        !nonNegative(newDoc.value) || !integer(newDoc.remaining_quantity) || newDoc.remaining_quantity < 0) {
      throw({forbidden: "voucher fields are invalid"});
    }
  }

  if (newDoc.type === "shipping_method") {
    if (!newDoc.code || !newDoc.name || !nonNegative(newDoc.fee) || typeof newDoc.active !== "boolean") {
      throw({forbidden: "shipping method fields are invalid"});
    }
  }

  if (newDoc.type === "order") {
    var statuses = ["pending", "confirmed", "packing", "shipping", "delivered", "cancelled"];
    if (statuses.indexOf(newDoc.status) === -1 || !newDoc.receiver || !newDoc.receiver.name ||
        !newDoc.receiver.phone || !newDoc.receiver.address || !Array.isArray(newDoc.items) || newDoc.items.length === 0) {
      throw({forbidden: "order requires a valid status, receiver, and non-empty items"});
    }
    if (!newDoc.totals || !nonNegative(newDoc.totals.total_quantity) ||
        !nonNegative(newDoc.totals.subtotal) || !nonNegative(newDoc.totals.shipping_fee) ||
        !nonNegative(newDoc.totals.discount_amount) || !nonNegative(newDoc.totals.grand_total) ||
        !Array.isArray(newDoc.status_history)) {
      throw({forbidden: "order totals and status_history are invalid"});
    }
    if (newDoc.payment_history !== undefined) {
      if (!Array.isArray(newDoc.payment_history)) { throw({forbidden: "payment_history must be an array"}); }
      for (var h = 0; h < newDoc.payment_history.length; h++) {
        var paymentEvent = newDoc.payment_history[h];
        if (!paymentEvent || typeof paymentEvent !== "object" || paymentEvent.status !== "paid" ||
            typeof paymentEvent.at !== "string" || paymentEvent.at.length === 0 ||
            typeof paymentEvent.source !== "string" || paymentEvent.source.length === 0 ||
            (paymentEvent.staff_id !== undefined && typeof paymentEvent.staff_id !== "string") ||
            (paymentEvent.customer_id !== undefined && typeof paymentEvent.customer_id !== "string") ||
            (paymentEvent.method !== undefined && typeof paymentEvent.method !== "string") ||
            (paymentEvent.verification !== undefined && paymentEvent.verification !== "manual")) {
          throw({forbidden: "payment_history entry is invalid"});
        }
      }
      if (oldDoc && Array.isArray(oldDoc.payment_history)) {
        if (newDoc.payment_history.length < oldDoc.payment_history.length) { throw({forbidden: "payment_history is append-only"}); }
        for (var e = 0; e < oldDoc.payment_history.length; e++) {
          if (JSON.stringify(newDoc.payment_history[e]) !== JSON.stringify(oldDoc.payment_history[e])) {
            throw({forbidden: "payment_history is append-only"});
          }
        }
      }
    }
    if (oldDoc && oldDoc.type === "order" && oldDoc.payment &&
        (oldDoc.payment.paid === true || oldDoc.payment.status === "paid") &&
        (!newDoc.payment || (newDoc.payment.paid !== true && newDoc.payment.status !== "paid"))) {
      throw({forbidden: "paid orders cannot be marked unpaid"});
    }
    for (var o = 0; o < newDoc.items.length; o++) {
      var orderItem = newDoc.items[o];
      if (!orderItem.product_id || !orderItem.variant_id || !integer(orderItem.quantity) ||
          orderItem.quantity <= 0 || !nonNegative(orderItem.unit_price) || !nonNegative(orderItem.line_total)) {
        throw({forbidden: "order item fields are invalid"});
      }
    }
  }

  if (newDoc.type === "review") {
    if (!newDoc.legacy_id || !newDoc.product_id || !newDoc.reviewer_name ||
        !integer(newDoc.rating) || newDoc.rating < 1 || newDoc.rating > 5 ||
        typeof newDoc.content !== "string" || typeof newDoc.active !== "boolean") {
      throw({forbidden: "review fields are invalid"});
    }
  }
}
